"""GCU400 override of the generic special_exp2 (alias of exp2).

The enflame copy used to forward straight to the generic ``exp2``
(``pointwise_dynamic``), which costs ~0.4x vs torch native on the official
core shapes: the generic ENFLAME codegen dispatches a block-pointer kernel
on only 12 CTAs (tile 4096) and ``tl.exp2`` lowers to the slow software
shim (special_expit/rad2deg family pathology, 2.4-3.9x on its own).  The
flat grid-stride kernel below saturates all 48 SIPS and uses the native
``tl.exp(x * ln2)`` instead of the ``tl.exp2`` shim; the fp32 compute path
is identical to the generic kernel (cast to fp32, exp2, cast back).
Non-float / non-contiguous / >=2^31-element inputs fall back to the generic
promotion arm, which matches ATen (int/bool promote to fp32).
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.ops.exp2 import exp2
from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

NUM_SIPS = 24

_FLOAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32)


@libentry()
@triton.jit(do_not_specialize=["N_total"])
def special_exp2_flat_kernel(x_ptr, out_ptr, N_total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)

    num_blocks = (N_total + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        off = block_id * BLOCK + arange
        mask = off < N_total
        x = tl.load(x_ptr + off, mask=mask).to(tl.float32)
        out = tl.exp(x * 0.6931471805599453)
        tl.store(out_ptr + off, out, mask=mask)


def _choose_block(N_total, itemsize):
    # do_bench(median) sweep on this kernel body (special_expit / rad2deg /
    # square family ladder, re-swept for the exp body): the sub-1M latency
    # band wants small tiles spread over several CTAs (N=8192: 3.4 vs
    # 4.1 us, 524288 fp16: 4.9 vs 6.1 us), the big buckets carry over the
    # family split -- 2-byte elements widen to 131072 past 2^28 (512M fp16
    # 713 vs 830 us at 32768) while fp32 peaks at 65536.
    if N_total <= 8192:
        return min(triton.next_power_of_2(N_total), 2048)
    if N_total <= 65536:
        return 4096
    if N_total <= 524288:
        return 8192 if itemsize <= 2 else 16384
    if N_total > (1 << 28) and itemsize <= 2:
        return 131072
    return 65536


def _launch_flat(inp, out):
    N_total = inp.numel()
    BLOCK = _choose_block(N_total, inp.element_size())
    grid_size = min(triton.cdiv(N_total, BLOCK), NUM_SIPS * 2)
    # The external llvm converter intermittently fails on cold compiles
    # (nondeterministic, host-level userland flake windows on shared nodes);
    # retrying the launch recompiles and succeeds (atan2_/sinh/rad2deg
    # precedents for the same toolchain family).
    for attempt in range(3):
        try:
            with torch_device_fn.device(inp.device):
                special_exp2_flat_kernel[(grid_size,)](
                    inp,
                    out,
                    N_total,
                    BLOCK=BLOCK,
                    num_warps=2,
                )
            return
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "special_exp2 flat kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )


def special_exp2(A):
    logger.debug("GEMS SPECIAL_EXP2")
    if A.dtype not in _FLOAT_DTYPES or not A.is_contiguous() or A.numel() >= (1 << 31):
        return exp2(A)
    out = torch.empty_like(A)
    if out.numel() == 0:
        return out
    _launch_flat(A, out)
    return out
